/bin/bash -lc "cat > /tmp/gbrain-install-docs/mcp-verify.mjs <<'EOF'
import { Client } from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js';
import { StdioClientTransport } from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/stdio.js';
const transport = new StdioClientTransport({command:'/harness-state/.gbrain/hook-launcher/gbrain-hook',args:['/harness-state/.bun/bin/gbrain','serve','--surface','starter','--advertise','verbs'],env:{...process.env,GBRAIN_HOME:'/harness-state'},stderr:'inherit'});
const client = new Client({name:'gbrain-install-verifier',version:'1.0.0'});
try {
 await client.connect(transport);
 const list=await client.listTools();
 const tools=list.tools.map(t=>({name:t.name,inputSchema:t.inputSchema}));
 await Bun.write('/tmp/gbrain-install-docs/mcp-tools.json',JSON.stringify(tools,null,2));
 console.log(JSON.stringify({tools:tools.map(t=>t.name)}));
 const result=await client.callTool({name:'recall',arguments:{entity:'gbrain-install-check'}});
 if(result.isError||"'!JSON.stringify(result).includes('"'cobalt otters balance seven lanterns'))throw Error('MCP recall did not return verification note: '+JSON.stringify(result));
 console.log(JSON.stringify({check:'MCP recall',result}));
 await Bun.write('/tmp/gbrain-install-docs/mcp-recall.json',JSON.stringify(result,null,2));
} finally {await client.close();}
EOF
/harness-state/.bun/bin/bun /tmp/gbrain-install-docs/mcp-verify.mjs"

